document.addEventListener("DOMContentLoaded",()=>{const o=document.querySelectorAll(".faq-item");o.forEach(e=>{const a=e.querySelector(".faq-trigger");a.addEventListener("click",()=>{var t=e.classList.contains("active");o.forEach(t=>{t.classList.remove("active"),t.querySelector(".faq-trigger").setAttribute("aria-expanded","false")}),t||(e.classList.add("active"),a.setAttribute("aria-expanded","true"))})})}),$(document).ready(function(){tns({container:".carrossell-banner",items:1,loop:!0,slideBy:"page",autoplayButtonOutput:!1,autoplay:!0,controls:!1,controlsPosition:"bottom",nav:!0})});